function contEspera_(p) { // v145: a escuta do PC do servidor deixa esta chamada esperando (até ~17 s) e ela volta na hora em que o Celio manda um comando
  if (String(p.chave || '') !== pChaveRele_()) return { ok: false, erro: 'chave inválida' };
  var comp = String(p.comp || '3'), c = CacheService.getScriptCache(), k = 'CONT_CMDP_' + comp, fim = Date.now() + 17000, ctrl = PropertiesService.getScriptProperties().getProperty('CONT_CONTROLE') === 'SIM';
  c.put('CONT_ESCUTA', String(Date.now()), 600);
  while (true) {
    if (ctrl) { var s = c.get(k); if (s) { try { var cmd = JSON.parse(s); if (cmd && cmd.status === 'PENDENTE') return { ok: true, cmd: cmd }; } catch (e) {} } }
    if (Date.now() > fim) return { ok: true };
    Utilities.sleep(500);
  }
}
function contFeito_(p) { // v145: a escuta confirma o comando (FEITO/ERRO)
  if (String(p.chave || '') !== pChaveRele_()) return { ok: false, erro: 'chave inválida' };
  if (p.cmdFeito) contCmdFeito_(String(p.comp || '3'), p.cmdFeito);
  return { ok: true };
}
